(() => {
 const M=IRRBB_MATH,m=x=>(x<0?'−':'')+'£'+Math.abs(x).toFixed(3)+'m',p=x=>(x*100).toFixed(2)+'%',a=(id,label,min,max,step,value,unit='£m')=>({id,label,min,max,step,value,unit}),sel=(id,label,options,value)=>({id,label,options,value});
 const sources={pra:['https://www.bankofengland.co.uk/prudential-regulation/publication/2013/the-internal-capital-adequacy-assessment-process-and-supervisory-review-ss','PRA SS31/15 · Chapter 2, IRRBB'],shock:['https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/liap/liaf0225app4.pdf','PRA2025/20 · ICAA 9.11; effective 1 July 2026'],basel:['https://www.bis.org/committees/bcbs/basel-framework/standard/srp/31/inforce/2026-01-01/published/2024-07-16','Basel SRP31 · 2026 standard'],guide:['https://www.bis.org/committees/bcbs/basel-framework/standard/srp/98/inforce/2026-01-01/published/2024-07-16','Basel SRP98 · measurement guidance'],disclosure:['https://www.bankofengland.co.uk/-/media/boe/files/prudential-regulation/regulatory-reporting/banking/pillar3-irrbb-instructions.pdf','PRA · UK IRRBB1 disclosure instructions'],capital:['https://www.bankofengland.co.uk/prudential-regulation/publication/2015/the-pras-methodologies-for-setting-pillar-2-capital','PRA SoP5/15 · Chapter 7, Pillar 2 IRRBB']};
 const sc=()=>sel('scenario','Interest-rate scenario',M.SCENARIOS,'up'),cc=()=>sel('currency','Shock calibration currency',Object.keys(M.SHOCKS).map(x=>[x,x]),'GBP');
 const bar=(labels,values)=>labels.map((label,i)=>({label,value:values[i],color:values[i]<0?'#b57e3e':['#285e46','#779db0','#93b77b'][i%3]}));
 const line=(name,color,fn,end=20)=>({name,color,data:Array.from({length:81},(_,i)=>[end*i/80,fn(end*i/80)])});
 const out=(stats,labels,values,rows,explanation,note='')=>({stats,bars:bar(labels,values),headers:['Step / quantity','Value','Interpretation'],rows,explanation,note});
 const opts=s=>({...M.defaults(),...s});
 window.IRRBB_LESSONS=[];const L=IRRBB_LESSONS;
 const add=l=>L.push({stage:'02 · Value and earnings',simpleTitle:'Build the intuition',key:'Δ = shocked result minus baseline. A negative ΔEVE or ΔNII is adverse to the bank. Amounts are £m equivalents unless stated. Teaching conventions are stated below.',notes:[],sources:[sources.pra,sources.guide],...l});
 add({id:'lab',name:'IRRBB balance-sheet lab',stage:'01 · Build → shock → explain',title:'Build a bank. Move the curve. Follow the impact.',intro:'Create cash flows for assets, funding and hedges. Compare six supervisory shocks, then inspect the valuation and interest-income effects row by row.',chart:'Your balance sheet under interest-rate shocks',inputs:[cc(),sc(),sel('view','Visualise',[['eve','ΔEVE across six shocks'],['nii','ΔNII across six shocks'],['curve','Selected curve shock']],'eve'),a('short','Baseline short zero rate',-2,10,.25,4,'%'),a('long','Baseline long zero rate',-2,10,.25,4,'%'),sel('floor','Post-shock curve floor',[['pra','PRA maturity-dependent floor'],['none','No floor · sensitivity only'],['zero','Zero floor · sensitivity only']],'pra'),sel('margins','EVE commercial margins',[['exclude','Exclude margins from cash flows'],['include','Include in cash flows and discount rates']],'exclude'),sel('balance','NII balance-sheet convention',[['constant','Constant balance · replace run-off'],['runoff','Run-off · no replacement']],'constant'),a('horizon','NII horizon',1,5,1,1,'years'),a('tier1','Tier 1 capital denominator',1,100,1,15)],challenge:'Try the matched-book preset, then extend only the asset maturity. Explain why EVE and NII need not move together.',formula:'EVE = Σ signed repricing cash flow × discount factor\nΔEVE = EVEshock − EVEbase\nNII = Σ monthly interest income − interest expense\nEVE decline / Tier 1 = max(0, −min ΔEVE) / Tier 1',simple:'A bank has promised to receive some payments and make others. Rate changes alter their present value and the rates at which future interest is earned or paid. The lab follows both stories, so a near-term earnings gain cannot hide a long-term value loss.',scope:'Single selected currency, with amounts displayed as £m equivalents; changing currency changes shock sizes, not FX conversion. Synthetic zero curve R(t)=short+(long−short)(1−exp(−t/5)); continuous discounting. EVE runs off the current book using exact-date cash flows, not the full Basel 19-bucket method. Floating principal is a repricing proxy at first reset, not cash actually repaid. NMDs use a core fixed-repricing proxy plus overnight non-core funds. Mortgage CPR and retail deposit withdrawals use Basel scenario scalars; automatic option add-ons, defaults and currency aggregation are omitted here. NII uses monthly accrual, stationary curve shifts, constant product spreads, no macroeconomic forecast; NMD balances are maintained in both conventions. One-year constant-balance parallel-shock NII is the disclosure-style view; other horizons/scenarios are internal illustrations. Swap fixed-versus-floating legs are simplified. The 15% ratio is an indicative screen, not a compliance determination.',sources:[sources.shock,sources.pra,sources.basel,sources.disclosure],compute(s){const book=window.IRRBB_BOOK||M.preset('retail'),r=M.portfolio(book,s),selected=r.scenarios.find(x=>x.id===s.scenario),v=s.view==='nii'?'dnii':'deve';const result={stats:[['Baseline EVE',m(r.baseEve)],['Baseline NII',m(r.baseNii)],['Worst EVE decline / Tier 1',p(r.ratio)]],bars:bar(r.scenarios.map(x=>x.label),r.scenarios.map(x=>x[v])),headers:['Scenario','Shocked EVE','ΔEVE','Shocked NII','ΔNII','NII interpretation'],rows:r.scenarios.map(x=>[x.label,m(x.eve),m(x.deve),m(x.nii),m(x.dnii),['up','down'].includes(x.id)?'Parallel supervisory shape':'Additional internal illustration']),explanation:`${r.worst.label} gives the largest EVE decline: ${m(r.loss)}, or ${p(r.ratio)} of Tier 1. Under ${selected.label}, ΔNII is ${m(selected.dnii)} over ${s.horizon} year(s). ${r.ratio>.15?'This teaching screen exceeds 15%; it is not the Pillar 2 capital charge.':'Remaining below 15% does not establish that all IRRBB is acceptable.'}`,note:`Calibration ${s.currency}: parallel / short / long = ${M.SHOCKS[s.currency].join(' / ')} bps. EVE always runs off; the NII convention is ${s.balance}.`,lab:{...r,options:s,selected,book}};if(s.view==='curve'){delete result.bars;result.series=[line('Baseline zero rate (%)','#779db0',t=>M.zero(t,s)*100),line(selected.label+' (%)','#285e46',t=>M.zero(t,s,s.scenario)*100)];result.xlabel='Years to cash flow';}return result;}});
 add({id:'cashflows',name:'Cash-flow construction',stage:'01 · Build → shock → explain',title:'A maturity date is not a cash-flow schedule',intro:'Compare a bullet loan with an amortising mortgage. The timing of returned principal changes how long money remains exposed.',chart:'Outstanding principal over time (£m)',inputs:[a('amount','Loan balance',0,200,5,100),a('rate','Annual coupon',0,10,.25,5,'%'),a('maturity','Maturity',1,30,1,10,'years'),a('cpr','Annual conditional prepayment rate',0,40,1,5,'%')],challenge:'Set prepayment to zero. Why does the mortgage balance still fall?',formula:'Monthly payment = P × rmonthly / [1 − (1 + rmonthly)^(−months)]\nMonthly prepayment fraction = 1 − (1 − CPR)^(1/12)',simple:'A bullet returns principal at the end. An amortising loan returns some earlier with each payment; prepayment accelerates that return further. Interest is earned on the balance still outstanding, so the schedule determines both value and future income.',scope:'Level-payment monthly amortisation with constant contractual rate and an annual CPR assumption. Interest is paid before scheduled principal and prepayment. No arrears, fees, defaults or prepayment penalties. Zero coupon uses equal principal repayment.',compute(s){const rows=M.loan(s.amount,s.rate,s.maturity,s.cpr),interest=M.sum(rows.map(x=>x.interest)),wal=s.amount?M.sum(rows.map(x=>x.t*x.principal))/s.amount:0;return {stats:[['Principal returned',m(M.sum(rows.map(x=>x.principal)))],['Total interest',m(interest)],['Principal-weighted life',wal.toFixed(2)+' years']],series:[{name:'Amortising balance',color:'#285e46',data:[[0,s.amount],...rows.map(x=>[x.t,x.balance])]}, {name:'Bullet balance',color:'#b57e3e',data:[[0,s.amount],[s.maturity-1/120,s.amount],[s.maturity,0]]}],xlabel:'Years',headers:['Month','Opening balance','Interest','Principal','Closing balance'],rows:rows.filter((x,i)=>i<12||i===rows.length-1).map((x,i)=>[(x.t*12).toFixed(0),m(x.opening),m(x.interest),m(x.principal),m(x.balance)]),explanation:`Principal-weighted life is ${wal.toFixed(2)} years versus contractual maturity ${s.maturity}. Faster return of principal shortens exposure and leaves less balance earning the original coupon.`,note:'Table shows the first twelve payments and the last payment. The lab can export the complete cash-flow detail.'};}});
 add({id:'shocks',name:'Six supervisory shocks',stage:'01 · Build → shock → explain',title:'Interest-rate risk is more than “rates up or down”',intro:'Compare parallel moves with short-rate shifts and rotations of the yield curve. The supervisory shape changes the shock at each cash-flow horizon.',chart:'Baseline and shocked zero curves (%)',inputs:[cc(),sc(),a('short','Baseline short rate',-2,10,.25,4,'%'),a('long','Baseline long rate',-2,10,.25,4,'%'),sel('floor','Floor convention',[['pra','PRA maturity-dependent'],['none','No floor · sensitivity']],'pra')],challenge:'Compare steepener and flattener at one year and ten years. Why can a single duration number miss this risk?',formula:'e(t)=exp(−t/4)\nShort shock = ±S × e(t)\nSteepener = −0.65S e(t) + 0.9L[1−e(t)]\nFlattener = 0.8S e(t) − 0.6L[1−e(t)]',simple:'A rotation can lower short rates while raising long rates. Assets and liabilities concentrated at different dates then see different shocks, even if their total amounts match.',scope:'PRA2025/20 and Basel 2026 currency shock magnitudes. Curve shapes are evaluated at exact tenors. The PRA floor rises from −1% at zero maturity by 5 bps a year to zero at 20 years; an already-lower baseline is retained. The no-floor option is an internal sensitivity, not the UK prescribed convention.',sources:[sources.shock,sources.basel,sources.pra],compute(s){const o=opts(s);return {stats:[['Parallel size',M.SHOCKS[s.currency][0]+' bps'],['Short size',M.SHOCKS[s.currency][1]+' bps'],['Long size',M.SHOCKS[s.currency][2]+' bps']],series:[line('Baseline','#779db0',t=>M.zero(t,o)*100,30),line('Shocked','#285e46',t=>M.zero(t,o,s.scenario)*100,30)],xlabel:'Tenor in years',headers:['Tenor','Raw shift','Baseline','After floor'],rows:[.25,1,2,5,10,20,30].map(t=>[t+'y',(M.shift(t,s.scenario,s.currency)*10000).toFixed(1)+' bps',p(M.zero(t,o)),p(M.zero(t,o,s.scenario))]),explanation:`The ${s.currency} ${M.SCENARIOS.find(x=>x[0]===s.scenario)[1]} shock changes each tenor according to its shape. Floors can make downward and upward effects asymmetric, especially near low starting rates.`,note:'Shock calibration is prescribed; the baseline curve is synthetic.'};}});
 add({id:'eve',name:'Economic value of equity',title:'Which promises lose more value when rates rise?',intro:'EVE compares the present value of asset receipts with liability payments. A fall in liability value can offset a fall in asset value.',chart:'Asset and liability contributions to ΔEVE (£m)',inputs:[a('assets','Fixed asset balance',0,200,5,100),a('liabilities','Fixed liability balance',0,200,5,90),a('assetT','Asset maturity',1,20,1,10,'years'),a('liabilityT','Liability maturity',1,20,1,2,'years'),a('shock','Parallel rate change',-300,300,25,200,'bps')],challenge:'Match maturities and coupons, then match balances. What happens to the net effect?',formula:'EVE = PV(assets) − PV(liabilities)\nΔEVE = ΔPV(assets) − ΔPV(liabilities)',simple:'A fixed promise far in the future becomes less valuable when discount rates rise. If the asset is locked for much longer than the funding, its loss in value can exceed the relief on the liability.',scope:'Annual-coupon bullet assets and liabilities at 4% coupon, baseline 4% continuous discount rate. Excludes own equity as a contractual cash flow. This is economic value, not accounting equity or regulatory capital.',compute(s){const a0=M.bond(s.assets,4,s.assetT,4),l0=M.bond(s.liabilities,4,s.liabilityT,4),da=M.bond(s.assets,4,s.assetT,4+s.shock/100)-a0,dl=M.bond(s.liabilities,4,s.liabilityT,4+s.shock/100)-l0;return out([['Baseline EVE',m(a0-l0)],['ΔEVE',m(da-dl)],['Shocked EVE',m(a0-l0+da-dl)]],['Asset ΔPV','Liability relief','Net ΔEVE'],[da,-dl,da-dl],[['Asset ΔPV',m(da),'Change in receipts'],['Liability ΔPV',m(dl),'Change in payments'],['Net difference',m(da-dl),'Subtract liability change']],`The asset contribution is ${m(da)} and the liability contribution is ${m(-dl)}. The bank’s net economic-value change is ${m(da-dl)}.`);}});
 add({id:'nii',name:'NII and reinvestment',title:'The next year’s earnings tell a different story',intro:'A fixed coupon stays fixed until reset or maturity. Floating receipts, deposit costs and replacement business respond on different schedules.',chart:'Cumulative net interest income (£m)',inputs:[a('reset','Floating asset first reset',1,12,1,3,'months'),a('beta','Deposit rate pass-through',0,100,5,40,'%'),a('horizon','Earnings horizon',1,5,1,1,'years'),sel('balance','Replacement convention',[['constant','Replace maturing balance'],['runoff','Let contractual balances run off']],'constant'),sc()],challenge:'Delay the loan reset and increase deposit beta. Why can higher rates squeeze earnings?',formula:'NII = Σmonth (asset balance × asset rate − liability balance × liability rate) / 12\nΔNII = shocked NII − baseline NII',simple:'A bank benefits from higher rates only to the extent its income reprices faster or more than its costs. A low deposit beta helps earnings while it persists; deposit competition can erode it.',scope:'£100m floating loans at 5%, maturity 2 years; £90m NMDs at 2%, one-month repricing lag. GBP supervisory shapes with flat 4% baseline. NMD balances are maintained in both conventions; loan run-off is replaced only in constant-balance mode. Simplified stationary curve shifts and monthly accrual, no new-business growth. One-year parallel shocks illustrate the disclosure perspective; PRA internal earnings assessment also considers longer planning horizons.',sources:[sources.pra,sources.disclosure,sources.guide],compute(s){const o=opts(s),rows=[M.row('Loans','float','asset',100,5,2,{reset:s.reset/12}),M.row('NMDs','nmd','liability',90,2,3,{beta:s.beta,reset:1/12})],series=id=>{let c=0;return Array.from({length:s.horizon*12},(_,i)=>{c+=M.sum(rows.map(r=>M.nii(r,o,id)[i].value));return[(i+1)/12,c]})},base=series('base'),shock=series(s.scenario),b=base.at(-1)[1],v=shock.at(-1)[1];return {stats:[['Baseline NII',m(b)],['Shocked NII',m(v)],['ΔNII',m(v-b)]],series:[{name:'Baseline NII',color:'#779db0',data:[[0,0],...base]},{name:'Shocked NII',color:'#285e46',data:[[0,0],...shock]}],xlabel:'Years of income',headers:['Year','Cumulative base','Cumulative shocked','Difference'],rows:base.filter((x,i)=>(i+1)%12===0).map(x=>{const y=shock.find(z=>z[0]===x[0]);return[x[0],m(x[1]),m(y[1]),m(y[1]-x[1])] }),explanation:`Over ${s.horizon} year(s), NII changes by ${m(v-b)}. The loan reset timing and ${s.beta}% deposit pass-through determine which side reprices first.`,note:'Principal repayments do not count as interest income.'};}});
 add({id:'gap',name:'Repricing gap',title:'A matched balance can still have mismatched timing',intro:'Compare the amount of assets and funding that can change rate within an earnings horizon.',chart:'Rate-sensitive balances and simplified income effect',inputs:[a('asset','Assets repricing within horizon',0,200,5,80),a('liability','Liabilities repricing within horizon',0,200,5,100),a('shock','Rate change',-300,300,25,200,'bps'),a('remaining','Time after repricing',0,1,.1,.5,'years')],challenge:'Keep total assets and liabilities equal but change which ones reprice soon. Is the book still protected?',formula:'Repricing gap = RSA − RSL\nApproximate ΔNII = gap × rate change × time remaining',simple:'Two sides can have the same balance but different dates when their rates change. A liability-sensitive gap means more funding than assets reprices soon, making an upward shock potentially painful for earnings.',scope:'One bucket; immediate equal pass-through after the stated repricing point, constant balances, no basis risk or optionality. The bar labels identify the differing units.',compute(s){const gap=s.asset-s.liability,v=gap*s.shock/10000*s.remaining;return out([['Repricing gap',m(gap)],['Approximate ΔNII',m(v)],['Time earning changed rate',s.remaining+' years']],['Asset balance','Liability balance','Gap balance'],[s.asset,s.liability,gap],[['Gap',m(gap),'Rate-sensitive assets minus liabilities'],['Rate change',s.shock+' bps','Same change both sides'],['Approximate ΔNII',m(v),'Gap × change × remaining time']],`The repricing gap is ${m(gap)}. Over ${s.remaining} years after repricing, the simple income effect is ${m(v)}. Equal total balance-sheet size does not imply equal repricing exposure.`);}});
 add({id:'duration',name:'Duration and convexity',title:'A small-shock estimate can miss a large move',intro:'Compare exact repricing of a fixed bond with its local duration estimate. Curvature becomes important as the shock grows.',chart:'Exact and duration-only change in value (£m)',inputs:[a('amount','Bond amount',0,200,5,100),a('maturity','Maturity',1,25,1,10,'years'),a('coupon','Coupon',0,10,.5,4,'%'),a('shock','Rate change',-400,400,25,200,'bps')],challenge:'Use a long maturity and a large rate decline. Why does the tangent stop following the value curve?',formula:'DV01 ≈ [PV(r−1bp) − PV(r+1bp)] / 2\nLinear ΔPV ≈ −DV01 × shock in bps',simple:'Duration describes the slope of value at today’s rate. It is useful locally, but the price curve bends. The bend is why a large shock deserves full cash-flow repricing.',scope:'Annual fixed coupon, continuous discounting, base yield 4%. Numerical DV01 is a positive conventional magnitude for a long fixed bond. This lesson does not include customer options.',compute(s){const pv=y=>M.bond(s.amount,s.coupon,s.maturity,y),base=pv(4),dv=(pv(3.99)-pv(4.01))/2,exact=pv(4+s.shock/100)-base,lin=-dv*s.shock;return {stats:[['DV01',m(dv)+' / bp'],['Exact ΔPV',m(exact)],['Linear error',m(lin-exact)]],series:[line('Exact ΔPV','#285e46',x=>pv(4+(x-400)/100)-base,800),line('Duration estimate','#b57e3e',x=>-dv*(x-400),800)].map(z=>({...z,data:z.data.map(([x,y])=>[x-400,y])})),xlabel:'Parallel shock (bps)',headers:['Method','ΔPV','Meaning'],rows:[['Exact',m(exact),'Reprice all cash flows'],['Duration only',m(lin),'Local slope approximation'],['Error',m(lin-exact),'Linear minus exact']],explanation:`The ${s.shock} bp shock produces exact ΔPV ${m(exact)}. The duration estimate differs by ${m(lin-exact)} because the bond’s value is curved in rates.`};}});
 add({id:'key-rate',name:'Key-rate and curve risk',title:'Zero parallel sensitivity does not mean zero curve risk',intro:'Offset short- and long-tenor sensitivities, then rotate the curve. Equal and opposite DV01 can conceal a steepener exposure.',chart:'Tenor contributions to approximate ΔEVE (£m)',inputs:[a('shortDV','Signed 2-year DV01',-1,1,.01,.1,'£m / bp'),a('longDV','Signed 10-year DV01',-1,1,.01,-.1,'£m / bp'),cc(),sc()],challenge:'Set the two sensitivities equal and opposite. Compare parallel up with steepener.',formula:'Approximate ΔEVE = −Σ tenor DV01 × shock(tenor) in bps',simple:'Parallel duration compresses a curve into one number. A long-short tenor position can disappear in that total while remaining exposed to the relative movement of different parts of the curve.',scope:'Two externally specified signed key-rate sensitivities, linear approximation only, using raw supervisory shocks without floors. Not a full repricing or complete key-rate decomposition.',sources:[sources.basel,sources.guide],compute(s){const short=-s.shortDV*M.shift(2,s.scenario,s.currency)*10000,long=-s.longDV*M.shift(10,s.scenario,s.currency)*10000;return out([['Parallel DV01',(s.shortDV+s.longDV).toFixed(3)+' £m/bp'],['2-year effect',m(short)],['Combined effect',m(short+long)]],['2-year contribution','10-year contribution','Net effect'],[short,long,short+long],[['2-year shift',(M.shift(2,s.scenario,s.currency)*10000).toFixed(1)+' bps','Raw curve shock'],['10-year shift',(M.shift(10,s.scenario,s.currency)*10000).toFixed(1)+' bps','Raw curve shock'],['ΔEVE proxy',m(short+long),'Sum of tenor contributions']],`The net parallel DV01 is ${(s.shortDV+s.longDV).toFixed(3)} £m/bp, but the selected shape gives approximate ΔEVE ${m(short+long)}.`);}});
 add({id:'basis',name:'Basis risk',title:'“Floating against floating” is not always a hedge',intro:'An asset linked to one benchmark and funding linked to another can reprice together in time but differently in amount.',chart:'Benchmark changes and net interest effect (£m)',inputs:[a('amount','Matched floating balances',0,200,5,100),a('assetMove','Asset benchmark movement',-300,300,25,100,'bps'),a('liabilityMove','Funding benchmark movement',-300,300,25,150,'bps'),a('years','Time at the changed rates',0,3,.25,1,'years')],challenge:'Move both benchmarks equally, then widen only the funding benchmark. What did matching reset dates fail to hedge?',formula:'ΔNII = balance × (asset benchmark shift − funding benchmark shift) × time',simple:'A bank may receive a market benchmark but pay a policy-linked or administered rate. Matching the dates does not make their relative spread stable. Basis risk is the risk that those rates stop moving together.',scope:'Equal balances, full simultaneous repricing, no floors or customer beta. Illustrates earnings basis risk; valuation basis risk also matters for longer cash-flow streams.',sources:[sources.capital,sources.guide],compute(s){const income=s.amount*s.assetMove/10000*s.years,expense=s.amount*s.liabilityMove/10000*s.years;return out([['Basis change',s.assetMove-s.liabilityMove+' bps'],['Income change',m(income)],['Net ΔNII',m(income-expense)]],['Income change','Expense impact','Net ΔNII'],[income,-expense,income-expense],[['Asset benchmark',s.assetMove+' bps','Receipt repricing'],['Funding benchmark',s.liabilityMove+' bps','Payment repricing'],['Residual',m(income-expense),'Different benchmark movements']],`Despite equal balances and reset dates, the basis movement creates ΔNII of ${m(income-expense)}.`);}});
 add({id:'nmd',name:'Non-maturity deposits',stage:'03 · Behaviour and options',title:'Withdrawable tomorrow can behave like longer funding',intro:'Separate core from non-core deposits and examine the standardised caps. Stability of balances and stability of pricing are different questions.',chart:'Core and overnight deposit balances (£m)',inputs:[a('amount','Deposit balance',0,200,5,100),sel('category','Basel standardised category',[['transactional','Retail transactional'],['retail','Retail non-transactional'],['wholesale','Wholesale']],'transactional'),a('core','Estimated core share',0,100,5,80,'%'),a('years','Estimated core average repricing',0,8,.5,5,'years')],challenge:'Choose wholesale deposits and raise the estimated core share to 90%. Why does the modelled share stop increasing?',formula:'Allowed core share = min(estimated share, category cap)\nAverage repricing proxy = core share × allowed core maturity + non-core share × overnight',simple:'A customer can withdraw on demand, but a pool of accounts may persist. That does not mean all those balances are insensitive to rates. Core modelling requires evidence about both withdrawal and repricing behaviour.',scope:'Basel SRP31.107–31.112 standardised caps: transactional 90% / 5 years; other retail 70% / 4.5 years; wholesale 50% / 4 years. This is a two-point slotting illustration. PRA SS31/15’s maximum average 5-year behavioural repricing constraint for relevant NMDs is a separate internal-model expectation, not a blanket 5-year term for every account.',sources:[sources.basel,sources.pra],compute(s){const c=M.nmdCaps(s.category,s.core,s.years),core=s.amount*c.core/100,non=s.amount-core,avg=c.core/100*c.years+(1-c.core/100)/365;return out([['Allowed core share',c.core+'%'],['Allowed core maturity',c.years+' years'],['Total repricing average',avg.toFixed(2)+' years']],['Core balance','Overnight balance'],[core,non],[['Category caps',c.cap+'% / '+c.maxYears+' years','Standardised maxima'],['Core balance',m(core),'Restricted by cap'],['Non-core balance',m(non),'Overnight proxy']],`The capped core balance is ${m(core)} with ${c.years} years average core repricing. A stable balance is not automatically a fixed-rate liability.`);}});
 add({id:'beta',name:'Deposit beta and lag',stage:'03 · Behaviour and options',title:'How much of a rate rise reaches depositors—and when?',intro:'Change the deposit pass-through and repricing delay to see how funding costs build through the year.',chart:'Cumulative deposit interest expense (£m)',inputs:[a('amount','Deposits',0,200,5,100),a('beta','Rate pass-through beta',0,100,5,40,'%'),a('lag','Delay before repricing',0,12,1,3,'months'),a('shock','Market rate movement',-300,300,25,200,'bps')],challenge:'Keep beta fixed and delay repricing. Does the long-run pricing response change, or only its timing?',formula:'Deposit rate after lag = max(0, current rate + beta × market-rate change)',simple:'Beta answers how much of the market move is passed on. Lag answers when it is passed on. Both can help near-term margins, but competitive pressure can change them together.',scope:'Constant deposit balance, starting paid rate 2%, a zero product-rate floor and one discrete repricing after the lag. Beta and lag are assumptions, not regulatory calibrations or forecasts.',compute(s){const newRate=Math.max(0,2+s.beta/100*s.shock/100),series=Array.from({length:13},(_,i)=>[i,s.amount*(2*Math.min(i,s.lag)+newRate*Math.max(0,i-s.lag))/1200]),base=s.amount*.02,sh=series.at(-1)[1];return {stats:[['New deposit rate',newRate.toFixed(2)+'%'],['Annual expense',m(sh)],['ΔNII from deposits',m(base-sh)]],series:[{name:'Shocked expense',color:'#b57e3e',data:series},{name:'Baseline expense',color:'#779db0',data:[[0,0],[12,base]]}],xlabel:'Months',headers:['Quantity','Value','Meaning'],rows:[['Beta',s.beta+'%','Rate change pass-through'],['Lag',s.lag+' months','Delay in paid-rate change'],['Extra expense',m(sh-base),'Reduces NII when positive']],explanation:`Deposits reprice to ${newRate.toFixed(2)}% after ${s.lag} months. The effect on this year’s NII is ${m(base-sh)}. The product floor limits benefits from falling rates.`};}});
 add({id:'prepayment',name:'Mortgage prepayment',stage:'03 · Behaviour and options',title:'Customers can give your attractive fixed loan back early',intro:'Apply supervisory prepayment multipliers to a baseline CPR and watch the balance—and future interest—change.',chart:'Baseline and scenario mortgage balances (£m)',inputs:[a('amount','Mortgage balance',0,200,5,100),a('rate','Fixed mortgage rate',0,10,.5,5,'%'),a('maturity','Remaining maturity',1,30,1,15,'years'),a('cpr','Baseline annual CPR',0,50,1,10,'%'),sc()],challenge:'Compare up and down shocks. Why can falling rates reduce the benefit of holding a high-coupon mortgage?',formula:'Scenario CPR = min(100%, baseline CPR × scenario scalar)\nScalars: 0.8 for up / steepener / short-up; 1.2 for down / flattener / short-down',simple:'A borrower who can refinance is more likely to repay when a cheaper loan becomes available. The bank receives principal back but loses a valuable stream of fixed interest, often reinvesting at a lower rate.',scope:'Basel standardised retail prepayment scalar applied to a level-payment loan. No penalties, borrower heterogeneity or calibrated refinancing model. The chart isolates cash-flow behaviour, not option value.',sources:[sources.basel,sources.guide],compute(s){const cpr=Math.min(100,s.cpr*M.cprFactor(s.scenario)),base=M.loan(s.amount,s.rate,s.maturity,s.cpr),sh=M.loan(s.amount,s.rate,s.maturity,cpr),diff=M.sum(sh.map(x=>x.interest))-M.sum(base.map(x=>x.interest));return {stats:[['Scenario multiplier',M.cprFactor(s.scenario)+'×'],['Scenario CPR',cpr.toFixed(1)+'%'],['Lifetime interest difference',m(diff)]],series:[{name:'Baseline balance',color:'#779db0',data:[[0,s.amount],...base.map(x=>[x.t,x.balance])]},{name:'Scenario balance',color:'#285e46',data:[[0,s.amount],...sh.map(x=>[x.t,x.balance])]}],xlabel:'Years',headers:['Measure','Baseline','Scenario'],rows:[['CPR',s.cpr+'%',cpr+'%'],['Total interest',m(M.sum(base.map(x=>x.interest))),m(M.sum(sh.map(x=>x.interest)))],['Principal returned',m(M.sum(base.map(x=>x.principal))),m(M.sum(sh.map(x=>x.principal)))]],explanation:`The selected shape applies a ${M.cprFactor(s.scenario)}× scalar. Principal is still returned, but the timing changes and lifetime contractual interest changes by ${m(diff)}.`};}});
 add({id:'redemption',name:'Early deposit withdrawal',stage:'03 · Behaviour and options',title:'Funding called “fixed term” may not stay for the term',intro:'Let depositors withdraw early and compare the remaining term funding with the amount moved overnight.',chart:'Revised deposit repricing balances (£m)',inputs:[a('amount','Term deposit balance',0,200,5,100),a('redemption','Baseline early withdrawal ratio',0,80,5,10,'%'),sc(),a('maturity','Contractual maturity',1,10,1,3,'years')],challenge:'Compare the steepener and flattener scalars with the prepayment lesson. Are the two products’ behavioural rules identical?',formula:'Scenario redemption ratio = min(100%, base ratio × scalar)\nEarly-withdrawn principal → overnight; remaining principal → contractual term',simple:'If the customer can break a deposit without compensating the bank for its economic cost, a fixed-term label overstates funding stability. The timing of liability payments changes and replacement funding may cost more.',scope:'Basel SRP31.122–31.126 retail term-deposit illustration. Redemption is a one-time proportion, not annual CPR. Scalars: 1.2 up / flattener / short-up; 0.8 down / steepener / short-down. Compensating penalties and wholesale automatic options require different treatment.',sources:[sources.basel],compute(s){const ratio=Math.min(1,s.redemption/100*M.withdrawalFactor(s.scenario)),early=s.amount*ratio;return out([['Scenario scalar',M.withdrawalFactor(s.scenario)+'×'],['Early withdrawal',m(early)],['Remaining term balance',m(s.amount-early)]],['Overnight','Contractual term'],[early,s.amount-early],[['Baseline ratio',s.redemption+'%','One-time balance proportion'],['Scenario ratio',p(ratio),'After multiplier'],['Remaining maturity',s.maturity+' years','For non-withdrawn balance']],`${m(early)} is moved to overnight in this scenario. That shortens the liability’s effective repricing profile even though the original contract says ${s.maturity} years.`);}});
 add({id:'options',name:'Caps, floors and optionality',stage:'03 · Behaviour and options',title:'A floating coupon can stop floating at its floor or cap',intro:'Move the market rate through a loan’s floor and cap. Compare it with uncapped floating funding.',chart:'Loan coupon and funding rate across market states (%)',inputs:[a('floorRate','Loan all-in floor',0,6,.25,2,'%'),a('capRate','Loan all-in cap',6,12,.25,8,'%'),a('spread','Loan spread',0,4,.25,1,'%'),a('market','Market rate',-2,10,.25,4,'%'),a('amount','Matched balances',0,200,5,100)],challenge:'Push rates beyond the loan cap. Why does the funding cost keep rising after asset income stops?',formula:'Loan coupon = min(cap, max(floor, benchmark + spread))\nAnnual NII = balance × (loan coupon − benchmark)',simple:'A cap or floor transfers part of the rate movement between the bank and its customer. A timing match is no longer enough: the coupon can respond nonlinearly to market rates.',scope:'One-year realised coupon-payoff illustration with no product floor on the funding leg. This is not option fair value. A full standardised EVE calculation treats automatic options separately, including the prescribed volatility stress; the lab does not implement that option add-on.',sources:[sources.basel,sources.guide],compute(s){const coupon=x=>M.clamp(x+s.spread,s.floorRate,s.capRate),income=s.amount*(coupon(s.market)-s.market)/100;return {stats:[['Loan coupon',coupon(s.market).toFixed(2)+'%'],['Funding rate',s.market+'%'],['Annual NII',m(income)]],series:[line('Loan coupon','#285e46',x=>coupon(x-2),12),line('Funding benchmark','#b57e3e',x=>x-2,12)].map(z=>({...z,data:z.data.map(([x,y])=>[x-2,y])})),xlabel:'Market rate (%)',headers:['Item','Value','Interpretation'],rows:[['Floor',s.floorRate+'%','Minimum loan coupon'],['Cap',s.capRate+'%','Maximum loan coupon'],['NII',m(income),'Coupon difference × balance']],explanation:`At a ${s.market}% market rate, the loan pays ${coupon(s.market).toFixed(2)}%. Annual NII is ${m(income)} because the funding benchmark is uncapped in this example.`};}});
 add({id:'hedging',name:'Swap hedging and trade-offs',stage:'04 · Manage the whole risk',title:'Hedge the fixed-rate asset—and watch the other scenarios',intro:'Add a pay-fixed, receive-floating swap to a fixed asset funded by shorter debt. Compare all six EVE shocks.',chart:'Unhedged and hedged ΔEVE (£m)',inputs:[a('hedge','Pay-fixed swap notional',0,150,5,50),a('maturity','Swap maturity',1,15,1,5,'years'),sc()],challenge:'Raise the hedge notional beyond the asset amount. Can an overhedge move the worst scenario?',formula:'Hedged ΔEVE = asset / funding ΔEVE + swap ΔEVE',simple:'A pay-fixed swap gives up fixed interest and receives floating interest, reducing the fixed-rate exposure of a long asset. Its effectiveness depends on maturity and curve shape, and its cash flows also affect earnings and liquidity.',scope:'£100m 5-year fixed asset and £90m 1-year fixed funding, 4% rates; swap represented as fixed pay and floating receive repricing legs with first reset at three months. Constant-balance one-year NII. No collateral, counterparty risk, transaction costs or hedge accounting.',sources:[sources.pra,sources.capital,sources.guide],compute(s){const o=opts(s),book=[M.row('Asset','fixed','asset',100,4,5),M.row('Funding','fixed','liability',90,4,1)],before=M.portfolio(book,o),after=M.portfolio([...book,M.row('Pay fixed swap','swap','liability',s.hedge,4,s.maturity)],o),selected=after.scenarios.find(x=>x.id===s.scenario);return {stats:[['Unhedged worst decline',m(before.loss)],['Hedged worst decline',m(after.loss)],['Selected hedged ΔNII',m(selected.dnii)]],series:[{name:'Unhedged ΔEVE',color:'#b57e3e',data:before.scenarios.map((x,i)=>[i+1,x.deve])},{name:'Hedged ΔEVE',color:'#285e46',data:after.scenarios.map((x,i)=>[i+1,x.deve])}],xlabel:'Scenario 1 up · 2 down · 3 steep · 4 flat · 5 short up · 6 short down',headers:['Scenario','Unhedged ΔEVE','Hedged ΔEVE'],rows:after.scenarios.map((x,i)=>[x.label,m(before.scenarios[i].deve),m(x.deve)]),explanation:`After adding ${m(s.hedge)} of pay-fixed swaps, the worst EVE decline is ${m(after.loss)} under ${after.worst.label}. Check all scenarios rather than selecting the hedge that improves only one result.`};}});
 add({id:'margins',name:'Commercial margins',stage:'04 · Manage the whole risk',title:'A margin convention changes what “value” measures',intro:'Include or exclude a commercial spread and use a consistent discounting convention. Compare its contribution to the value sensitivity.',chart:'EVE sensitivity under two margin conventions (£m)',inputs:[a('amount','Fixed loan amount',0,200,5,100),a('margin','Commercial margin',0,5,.25,1,'%'),a('maturity','Loan maturity',1,20,1,5,'years'),sc()],challenge:'Set margin to zero. Why should both calculations coincide?',formula:'Excluded: coupon net of margin; risk-free discount curve\nIncluded: full coupon; discount curve includes margin',simple:'The contractual coupon includes more than compensation for the risk-free rate. If a model includes commercial spread cash flows but discounts them on a basis that omits the same spread, its result answers a different question.',scope:'PRA SS31/15 2.9B(viii) consistency illustration. Loan rate equals 4% plus chosen margin, flat 4% base curve, identical rate shocks. The spread itself is held fixed. NII retains contractual income; the margin switch applies to EVE.',sources:[sources.pra,sources.disclosure],compute(s){const row=M.row('Loan','fixed','asset',s.amount,4+s.margin,s.maturity,{margin:s.margin}),o=opts(s),excluded=M.value(row,{...o,margins:'exclude'},s.scenario)-M.value(row,{...o,margins:'exclude'}),included=M.value(row,{...o,margins:'include'},s.scenario)-M.value(row,{...o,margins:'include'});return out([['Margin excluded ΔPV',m(excluded)],['Margin included ΔPV',m(included)],['Difference',m(included-excluded)]],['Margin excluded','Margin included'],[excluded,included],[['Excluded',m(excluded),'Net coupon / risk-free discount'],['Included',m(included),'Gross coupon / margin-adjusted discount']],`The two consistent conventions differ by ${m(included-excluded)}. The example changes the treatment of margins, not the loan contract.`);}});
 add({id:'csrbb',name:'CSRBB and liquidity links',stage:'04 · Manage the whole risk',title:'A bond can lose value even when risk-free rates stay still',intro:'Separate a risk-free curve move from a credit or liquidity spread move. Then connect valuation losses to potential liquidity pressure.',chart:'Rate, spread and combined bond value changes (£m)',inputs:[a('amount','Banking-book bond',0,200,5,100),a('maturity','Maturity',1,20,1,5,'years'),a('rateMove','Risk-free rate movement',-200,300,25,0,'bps'),a('spreadMove','Market spread movement',-100,400,25,100,'bps')],challenge:'Keep the risk-free curve unchanged and widen only the spread. Which risk remains?',formula:'Bond discount yield = risk-free rate + market spread\nCombined ΔPV generally differs from the sum of separately repriced changes',simple:'Market spreads can widen because investors demand more credit or liquidity compensation. Those changes can hit banking-book values even without a risk-free rate shock. Separately, deposit withdrawals or collateral calls can force a bank to realise losses it had expected to hold through.',scope:'Annual coupon bond at 5%, starting discount yield 5% = 4% risk-free plus 1% spread. Illustrates market spread sensitivity; issuer default loss, CVA and liquidity cash-flow simulation are outside scope. CSRBB complements IRRBB and is not added mechanically to the EVE outlier numerator.',sources:[sources.pra,sources.guide],compute(s){const f=y=>M.bond(s.amount,5,s.maturity,y),base=f(5),r=f(5+s.rateMove/100)-base,c=f(5+s.spreadMove/100)-base,both=f(5+(s.rateMove+s.spreadMove)/100)-base;return out([['Rate-only ΔPV',m(r)],['Spread-only ΔPV',m(c)],['Combined ΔPV',m(both)]],['Rate effect','Spread effect','Combined effect'],[r,c,both],[['Risk-free shift',s.rateMove+' bps','IRRBB rate driver'],['Spread shift',s.spreadMove+' bps','Separate market-spread driver'],['Combined',m(both),'Full repricing']],`The spread move alone changes value by ${m(c)}, even if the risk-free move is zero. Economic-value loss and immediate liquidity need are related but different risks.`);}});
 add({id:'currencies',name:'Currency aggregation',stage:'04 · Manage the whole risk',title:'A gain in one currency may not fully cancel a loss in another',intro:'Apply the PRA’s 50% weighting of positive currency ΔEVE in a single common shock scenario.',chart:'Raw and weighted currency contributions (£m)',inputs:[a('gbp','GBP ΔEVE in reporting currency',-20,20,.5,-8),a('usd','USD ΔEVE in reporting currency',-20,20,.5,6),a('eur','EUR ΔEVE in reporting currency',-20,20,.5,1),a('tier1','Tier 1 capital',1,100,1,30)],challenge:'Make every currency a loss. Does the gain weighting still change the answer?',formula:'PRA scenario aggregate = Σ min(ΔEVEcurrency,0) + 50% × Σ max(ΔEVEcurrency,0)',simple:'A cross-currency gain is not always as reliable an offset as a same-currency hedge. The aggregation convention limits the amount of favourable currency movement recognised in the scenario.',scope:'PRA SS31/15 2.9B(iv). Inputs are already converted into one reporting currency and refer to the same supervisory scenario. A full screen repeats this process for every shock and selects the worst aggregate; do not sum each currency’s separate worst case.',sources:[sources.pra],compute(s){const raw=s.gbp+s.usd+s.eur,w=x=>x>0?.5*x:x,aggregate=w(s.gbp)+w(s.usd)+w(s.eur);return out([['Unweighted sum',m(raw)],['PRA-weighted sum',m(aggregate)],['Scenario decline / Tier 1',p(Math.max(0,-aggregate)/s.tier1)]],['GBP weighted','USD weighted','EUR weighted','Aggregate'],[w(s.gbp),w(s.usd),w(s.eur),aggregate],[['GBP',m(w(s.gbp)),'Loss full / gain half'],['USD',m(w(s.usd)),'Loss full / gain half'],['EUR',m(w(s.eur)),'Loss full / gain half']],`The unweighted result is ${m(raw)}; weighting positive contributions at 50% gives ${m(aggregate)}. Aggregate matching scenarios before taking the worst decline.`);}});
 add({id:'governance',name:'Outlier tests and governance',stage:'05 · Challenge the result',title:'A threshold is a trigger for review, not a complete risk policy',intro:'Compare an EVE decline with Tier 1 capital, then examine how model uncertainty can move the screen.',chart:'Base and stressed-assumption EVE decline versus threshold (£m)',inputs:[a('loss','Largest modelled EVE decline',0,30,.5,4),a('uncertainty','Additional adverse model sensitivity',0,15,.5,1),a('tier1','Tier 1 capital',1,100,1,30)],challenge:'Raise Tier 1 without changing the cash flows. Has the underlying rate exposure improved?',formula:'Indicative EVE outlier ratio = largest EVE decline / Tier 1 capital\nPRA notification trigger: decline greater than 15% of Tier 1',simple:'The denominator measures capacity to absorb loss, not the source of the loss. A model can pass a numerical screen and still have weak deposit assumptions, missing options, poor data or excessive earnings risk.',scope:'PRA SS31/15 2.7B and 2.8–2.10. A breach is not an automatic Pillar 2 capital amount, and the 15% line is not an NII threshold. The extra sensitivity is a user-defined challenge, not a prescribed add-on. EVE should be assessed at least quarterly; governance includes model validation, data reconciliation, limits, escalation and review of earnings.',sources:[sources.pra,sources.capital,sources.disclosure],compute(s){const stressed=s.loss+s.uncertainty,limit=.15*s.tier1;return out([['Base decline / Tier 1',p(s.loss/s.tier1)],['Challenged ratio',p(stressed/s.tier1)],['15% amount',m(limit)]],['Base decline','Challenged decline','15% of Tier 1'],[s.loss,stressed,limit],[['Base screen',s.loss>limit?'Above 15%':'At or below 15%','Indicative only'],['Assumption challenge',stressed>limit?'Above 15%':'At or below 15%','Sensitivity, not prescribed capital'],['Next review','Cash flows → assumptions → limits','Reconcile, validate, challenge']],`The base ratio is ${p(s.loss/s.tier1)}; adding the assumed model sensitivity makes it ${p(stressed/s.tier1)}. ${stressed>limit?'The challenged result exceeds the illustrative 15% line.':'This does not establish that earnings risk or governance is satisfactory.'}`, 'A real supervisory determination requires the complete applicable calculation, firm scope and current rules.');}});
 window.IRRBB_UI={m,p,bar,sources};
})();
